    public void lockChannel(String channelId, long nowNanos) {
        Integer exists = jdbc.queryForObject("SELECT COUNT(*) FROM channel_mutex WHERE channel_id = ?",
                Integer.class, channelId);
        if (exists == null || exists == 0) {
            try {
